CREATE OR REPLACE FUNCTION public.crear_queja_interna(p_cliente_nombre text, p_email_cliente text, p_categoria text, p_descripcion text, p_prioridad text)
 RETURNS quejas
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE q public.quejas;
BEGIN
 IF auth.uid() IS NULL OR NOT (coalesce(public.app_es_admin(), false)
 OR (coalesce(public.app_es_staff(), false) AND coalesce(public.app_tiene_permiso('quejas', true), false))) THEN
 RAISE EXCEPTION 'No autorizado.' USING ERRCODE = '42501';
 END IF;
 -- El trigger valida también llamadas directas y calcula tipo/recepción/plazo.
 INSERT INTO public.quejas(folio,cliente_nombre,email_cliente,categoria,descripcion,estado,fecha)
 VALUES(public.generar_folio_queja(),btrim(p_cliente_nombre),btrim(p_email_cliente),
 btrim(p_categoria),btrim(p_descripcion),'Recibido',now()) RETURNING * INTO q;
 INSERT INTO public.logs(fecha,usuario_id,accion,modulo,detalle)
 VALUES(now(),public.app_usuario_actual_id(),'crear','quejas','Queja interna ' || q.folio || ' creada');
 RETURN q;
END;
$function$

CREATE OR REPLACE FUNCTION public.public_form_finalize_submission(p_form_id uuid, p_submission_id uuid, p_queja_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_submission public.public_form_submissions%ROWTYPE; v_folio text;
BEGIN
 SELECT s.* INTO v_submission FROM public.public_form_submissions s WHERE s.form_id = p_form_id AND s.submission_id = p_submission_id AND s.queja_id = p_queja_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'PUBLIC_SUBMISSION_UNAVAILABLE'; END IF;
 SELECT folio INTO STRICT v_folio FROM public.quejas WHERE id = p_queja_id;
 IF v_submission.finalized_at IS NOT NULL THEN RETURN jsonb_build_object('folio',v_folio,'finalized',true); END IF;
 PERFORM 1 FROM public.formularios_publicos WHERE id = p_form_id AND activo AND modulo = 'quejas' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'PUBLIC_FORM_UNAVAILABLE'; END IF;
 IF EXISTS (SELECT 1 FROM public.public_form_uploads WHERE form_id = p_form_id AND submission_id = p_submission_id AND status = 'reserved') THEN
 RAISE EXCEPTION USING ERRCODE = '23505', MESSAGE = 'PUBLIC_UPLOAD_PENDING';
 END IF;
 -- Marca y notificaciones/mail_queue se confirman juntas bajo el mismo lock.
 PERFORM public.notificar_queja_publica(v_folio);
 UPDATE public.public_form_submissions SET finalized_at = now() WHERE form_id = p_form_id AND submission_id = p_submission_id;
 RETURN jsonb_build_object('folio',v_folio,'finalized',true);
END;
$function$

CREATE OR REPLACE FUNCTION public.qms_transition_complaint(p_id uuid, p_expected bigint, p_state text, p_resolution text DEFAULT NULL::text, p_justification text DEFAULT NULL::text, p_owner uuid DEFAULT NULL::uuid, p_reopen text DEFAULT NULL::text, p_office_number text DEFAULT NULL::text, p_resolution_format text DEFAULT NULL::text, p_justification_format text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE q public.quejas; own_revision bigint; office text; staff boolean;
BEGIN
 SELECT * INTO q FROM public.quejas WHERE id = p_id FOR UPDATE;
 staff := coalesce(public.app_es_admin(), false)
 OR (coalesce(public.app_es_staff(), false) AND coalesce(public.app_tiene_permiso('quejas', true), false));
 IF auth.uid() IS NULL OR NOT (staff OR (coalesce(public.app_es_colaborador(), false)
 AND coalesce(public.app_tiene_permiso('mis_quejas', true), false)
 AND coalesce(q.responsable_id = public.app_usuario_actual_id(), false))) THEN
 RAISE EXCEPTION 'No autorizado.' USING ERRCODE = '42501';
 END IF;
 IF q.id IS NULL THEN RAISE EXCEPTION 'Queja no encontrada.' USING ERRCODE = 'P0002'; END IF;
 IF p_expected IS NULL OR q.revision IS DISTINCT FROM p_expected THEN
 RAISE EXCEPTION 'Otra persona modificó la queja. Actualiza antes de guardar.' USING ERRCODE = '40001';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM public.catalogos WHERE modulo = 'quejas' AND tipo = 'estado_queja'
 AND codigo = p_state AND coalesce(activo, true)) THEN
 RAISE EXCEPTION 'Estado no reconocido.' USING ERRCODE = '22023';
 END IF;
 IF p_resolution_format IS NOT NULL AND (p_resolution IS NULL OR p_resolution_format NOT IN ('plain','markdown'))
 OR p_justification_format IS NOT NULL AND (p_justification IS NULL OR p_justification_format NOT IN ('plain','markdown'))
 OR length(coalesce(p_resolution, '')) > 10000 OR length(coalesce(p_justification, '')) > 10000
 OR length(coalesce(p_reopen, '')) > 10000 THEN
 RAISE EXCEPTION 'Texto o formato inválido.' USING ERRCODE = '22023';
 END IF;
 office := coalesce(nullif(btrim(p_office_number), ''), q.numero_oficio_resolucion);
 IF length(office) > 120 OR (p_state IN ('rejected','resolved','finished') AND office IS NULL) THEN
 RAISE EXCEPTION 'La respuesta final necesita un número de oficio válido.' USING ERRCODE = '22023';
 END IF;
 IF p_owner IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.usuarios WHERE id = p_owner AND estado = 'activo') THEN
 RAISE EXCEPTION 'Seleccioná un responsable activo.' USING ERRCODE = '22023';
 END IF;
 -- Se valida la revisión original ANTES de nuestra escritura bajo el mismo lock.
 -- La revisión enviada al motor es exclusivamente la producida por esta operación.
 UPDATE public.quejas SET numero_oficio_resolucion = office,
 resolucion_formato = CASE WHEN p_resolution IS NULL THEN resolucion_formato ELSE coalesce(p_resolution_format, 'plain') END,
 justificacion_procede = CASE WHEN p_justification IS NULL THEN justificacion_procede ELSE nullif(btrim(p_justification), '') END,
 justificacion_procede_formato = CASE WHEN p_justification IS NULL THEN justificacion_procede_formato ELSE coalesce(p_justification_format, 'plain') END
 WHERE id = p_id RETURNING revision INTO own_revision;
 PERFORM public.qms_transition(p_id, own_revision, p_state, p_resolution, p_justification, p_owner, p_reopen);
 RETURN (SELECT to_jsonb(v) FROM public.qms_quejas v WHERE v.id = p_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.qms_update_details(p_id uuid, p_expected bigint, p_categoria text DEFAULT NULL::text, p_prioridad text DEFAULT NULL::text, p_owner uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE q quejas;
BEGIN
 IF auth.uid() IS NULL OR NOT (coalesce(public.app_es_admin(),false) OR (coalesce(public.app_es_staff(),false) AND coalesce(public.app_tiene_permiso('quejas',true),false))) THEN RAISE EXCEPTION 'No autorizado' USING ERRCODE='42501'; END IF;
 SELECT * INTO q FROM quejas WHERE id=p_id FOR UPDATE;
 IF p_expected IS NULL OR q.revision IS DISTINCT FROM p_expected THEN RAISE EXCEPTION 'Otra persona modificó la queja. Actualiza antes de guardar.' USING ERRCODE='40001'; END IF;
 PERFORM public.actualizar_detalles_queja(p_id,p_categoria,p_prioridad,p_owner,p_notes);
 RETURN (SELECT to_jsonb(v) FROM qms_quejas v WHERE id=p_id);
END; $function$

CREATE OR REPLACE FUNCTION public.transicionar_queja(p_queja_id uuid, p_nuevo_estado text, p_resolucion text DEFAULT NULL::text, p_justificacion_procede text DEFAULT NULL::text, p_responsable_id uuid DEFAULT NULL::uuid, p_motivo_reapertura text DEFAULT NULL::text)
 RETURNS quejas
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
 v_queja public.quejas;
 v_usuario_id uuid;
 v_es_staff boolean;
 v_es_responsable boolean;
 v_destino record;
 v_mensaje text;
BEGIN
 v_usuario_id := public.app_usuario_actual_id();
 IF v_usuario_id IS NULL THEN RAISE EXCEPTION 'No autorizado'; END IF;

 SELECT * INTO v_queja FROM public.quejas WHERE id = p_queja_id FOR UPDATE;
 IF v_queja.id IS NULL THEN RAISE EXCEPTION 'Queja no encontrada'; END IF;

 v_es_staff := public.app_es_staff();
 v_es_responsable := (v_queja.responsable_id = v_usuario_id);
 IF NOT (v_es_staff OR (public.app_es_colaborador() AND v_es_responsable)) THEN
 RAISE EXCEPTION 'No autorizado';
 END IF;

 IF v_queja.estado = 'Recibido' AND p_nuevo_estado = 'En Investigación' THEN
 IF NOT v_es_staff THEN RAISE EXCEPTION 'Solo el personal de calidad puede iniciar la investigación'; END IF;
 UPDATE public.quejas
 SET estado = p_nuevo_estado,
 fecha_limite_investigacion = now() + interval '15 days',
 responsable_id = COALESCE(p_responsable_id, responsable_id),
 notas = CASE WHEN btrim(COALESCE(p_justificacion_procede, '')) <> ''
 THEN COALESCE(notas, '') || E'\n[Procede] ' || btrim(p_justificacion_procede)
 ELSE notas END
 WHERE id = p_queja_id RETURNING * INTO v_queja;

 ELSIF v_queja.estado = 'Recibido' AND p_nuevo_estado = 'No Procede' AND btrim(COALESCE(p_resolucion, '')) <> '' THEN
 IF NOT v_es_staff THEN RAISE EXCEPTION 'Solo el personal de calidad puede marcar como No Procede'; END IF;
 UPDATE public.quejas SET estado = p_nuevo_estado, resolucion = btrim(p_resolucion), fecha_cierre = now()
 WHERE id = p_queja_id RETURNING * INTO v_queja;

 ELSIF v_queja.estado = 'En Investigación' AND p_nuevo_estado = 'Pendiente de Revisión GC' AND btrim(COALESCE(p_resolucion, '')) <> '' THEN
 UPDATE public.quejas SET estado = p_nuevo_estado, resolucion = btrim(p_resolucion)
 WHERE id = p_queja_id RETURNING * INTO v_queja;

 ELSIF v_queja.estado = 'En Investigación' AND p_nuevo_estado = 'Resuelto' AND btrim(COALESCE(p_resolucion, '')) <> '' THEN
 IF NOT v_es_staff THEN RAISE EXCEPTION 'Solo el personal de calidad puede resolver directamente'; END IF;
 UPDATE public.quejas SET estado = p_nuevo_estado, resolucion = btrim(p_resolucion)
 WHERE id = p_queja_id RETURNING * INTO v_queja;

 ELSIF v_queja.estado = 'Pendiente de Revisión GC' AND p_nuevo_estado = 'Resuelto' THEN
 IF NOT v_es_staff THEN RAISE EXCEPTION 'Solo el personal de calidad puede aprobar la resolución'; END IF;
 UPDATE public.quejas SET estado = p_nuevo_estado, fecha_cierre = COALESCE(fecha_cierre, now())
 WHERE id = p_queja_id RETURNING * INTO v_queja;

 ELSIF v_queja.estado = 'Pendiente de Revisión GC' AND p_nuevo_estado = 'En Investigación' THEN
 IF NOT v_es_staff THEN RAISE EXCEPTION 'Solo el personal de calidad puede devolver la queja'; END IF;
 UPDATE public.quejas SET estado = p_nuevo_estado, resolucion = NULL
 WHERE id = p_queja_id RETURNING * INTO v_queja;

 ELSIF v_queja.estado = 'Resuelto' AND p_nuevo_estado = 'Finalizado' THEN
 IF NOT v_es_staff THEN RAISE EXCEPTION 'Solo el personal de calidad puede finalizar la queja'; END IF;
 UPDATE public.quejas SET estado = p_nuevo_estado, fecha_cierre = COALESCE(fecha_cierre, now())
 WHERE id = p_queja_id RETURNING * INTO v_queja;

 ELSIF v_queja.estado IN ('Resuelto', 'Finalizado') AND p_nuevo_estado = 'En Investigación' AND btrim(COALESCE(p_motivo_reapertura, '')) <> '' THEN
 IF NOT v_es_staff THEN RAISE EXCEPTION 'Solo el personal de calidad puede reabrir la queja'; END IF;
 UPDATE public.quejas
 SET estado = 'En Investigación',
 fecha_limite_investigacion = now() + interval '15 days',
 resolucion = NULL,
 notas = COALESCE(notas, '') || E'\n[Reapertura] ' || btrim(p_motivo_reapertura)
 WHERE id = p_queja_id RETURNING * INTO v_queja;

 ELSE
 RAISE EXCEPTION 'Transición no permitida: % → %', v_queja.estado, p_nuevo_estado;
 END IF;

 v_mensaje := 'La queja ' || v_queja.folio || ' cambió a ' || v_queja.estado || '.';
 FOR v_destino IN
 SELECT id FROM public.usuarios
 WHERE (id = v_queja.responsable_id OR rol IN ('admin', 'calidad'))
 AND estado = 'activo'
 AND id IS DISTINCT FROM v_usuario_id
 LOOP
 INSERT INTO public.notificaciones (usuario_id, fecha, tipo, mensaje, enlace, origen_id)
 VALUES (v_destino.id, now(), 'queja_estado', v_mensaje, '/quejas', v_queja.id);
 END LOOP;

 INSERT INTO public.logs (fecha, usuario_id, accion, modulo, detalle)
 VALUES (now(), v_usuario_id, 'transición', 'quejas', v_mensaje);
 RETURN v_queja;
END;
$function$
